"""Offline HIA continuation authoring for the complete native build coordinator.

The original nine bodies, their closures and rejection helper are fixed inputs.
All business flow is emitted into HIA. With regions use separate HIA frames
sharing the original named cells; the runtime port supplies only the actual
CPython context-manager protocol, never a retained Python policy body.
"""
from __future__ import annotations

import ast
from copy import deepcopy
from types import CodeType

from tools.hia_core_lowering_control import Function as _Function
from tools.hia_machine_plan_control import Compiler as _Compiler, OPS, PACK, COMPARE

ENTRIES=('_implementation_hash','validate_block_layout_plan','emit_program_machine',
         '_inspect_object','_read_artifact','_run_logged','_host',
         'compile_program_machine','build_program_machine','_reject')
WITH_REGION=250
RERAISE=251
DICT_UPDATE=253
MAPPING_PREPARE=254
MAPPING_CALL=255


class Compiler(_Compiler):
    def __init__(self,source):
        self.source,self.tree=source,ast.parse(source)
        self.lexical_codes={}
        def remember(code):
            for item in code.co_consts:
                if isinstance(item,CodeType):
                    key=(item.co_firstlineno,item.co_name)
                    if key in self.lexical_codes:
                        raise ValueError('ambiguous native-build lexical frame')
                    self.lexical_codes[key]=item
                    remember(item)
        remember(compile(source,'<native-build-lexical-layout>','exec'))
        self.imports={}
        for node in ast.walk(self.tree):
            if isinstance(node,ast.ImportFrom):
                if node.level!=1:raise ValueError('native-build import must be package-relative')
                self.imports.setdefault(node.module,set()).update(a.name for a in node.names)
        self.literals,self.literal_indices=[],{}
        self.functions,self.by_name=[],{}
        for node in self.tree.body:
            if isinstance(node,ast.Expr) and isinstance(node.value,ast.Constant) and type(node.value.value) is str:
                continue
            if not isinstance(node,ast.FunctionDef) or node.decorator_list:
                raise ValueError('unreviewed native-build policy declaration')
            function=Function(self,node.name,node)
            self.functions.append(function); self.by_name[node.name]=function
        if tuple(self.by_name)!=ENTRIES:
            raise ValueError('complete native-build entry inventory differs')
        index=0
        while index<len(self.functions):
            self.functions[index].compile(); index+=1
        for mode,function in enumerate(self.functions,1):function.mode=mode
        for function in self.functions:function.resolve()
        self._validate_calls()

    def literal(self,value):
        if type(value) is bytes:
            key=(bytes,value)
            if key not in self.literal_indices:
                self.literal_indices[key]=len(self.literals); self.literals.append(value)
            return self.literal_indices[key]
        return super().literal(value)

    def nested(self,parent,node,kind):
        function=Function(self,parent.name+':'+kind+':'+str(len(self.functions)),
                          node,parent=parent,kind=kind)
        self.functions.append(function)
        return function

    def region(self,parent,node):
        # All original named locals remain in the original physical order.
        # The region holds the same cells, including locals not yet assigned,
        # so a retained traceback sees subsequent binding changes as before.
        function=Function(self,parent.name+':with:'+str(len(self.functions)),
                          node,parent=parent,kind='with_region')
        self.functions.append(function)
        return function

    def _validate_calls(self):
        for fn in self.functions:
            for instruction in fn.instructions:
                if instruction['kind']!='effect' or instruction['opcode']!=OPS['CALL']:
                    continue
                raw,args=instruction['raw'],instruction['arguments']
                if len(raw)>=2 and raw[1] in (WITH_REGION,RERAISE,DICT_UPDATE,MAPPING_PREPARE,MAPPING_CALL):
                    continue
                if (len(raw)<2 or len(raw)!=2+raw[1] or len(args)!=1+raw[0]+raw[1]
                        or instruction['consume']!=args or len({r.slot for r in args})!=len(args)
                        or any(not r.temporary or r.slot in fn.cell_slots for r in args)):
                    raise ValueError('native-build CALL lacks unique consumed stack operands')


class Function(_Function):
    def __init__(self,compiler,name,node,*,parent=None,kind='function'):
        if kind=='with_region':
            empty=ast.FunctionDef(name='_with_region',args=ast.arguments(posonlyargs=[],args=[],
                vararg=None,kwonlyargs=[],kw_defaults=[],kwarg=None,defaults=[]),
                body=[],decorator_list=[])
            ast.copy_location(empty,node); ast.fix_missing_locations(empty)
            super().__init__(compiler,name,empty,parent=parent,kind='function')
            self.kind,self.node='with_region',node
            original={**parent.locals,**{key:pair[0] for key,pair in parent.captures.items()}}
            for local_name,outer in original.items():
                parent.cell_slots.add(outer.slot)
                own=self.slot(False)
                self.captures[local_name]=(own,outer)
            self.lexical_names=tuple(original)
            self.lexical_cells=()
            self.lexical_freevars=tuple(original)
            self.read_kinds={own.slot:parent.read_kinds[outer.slot]
                             for own,outer in self.captures.values()}
            return
        scanned=deepcopy(node)
        class ScopeScan(ast.NodeTransformer):
            def visit_FunctionDef(self,value):
                if value is scanned:return self.generic_visit(value)
                return ast.copy_location(ast.Assign(targets=[ast.Name(id=value.name,ctx=ast.Store())],
                    value=ast.Constant(None)),value)
        if kind=='function':scanned=ast.fix_missing_locations(ScopeScan().visit(scanned))
        if getattr(scanned,'args',None) and scanned.args.kwarg:
            scanned.args.kwonlyargs.append(scanned.args.kwarg)
            scanned.args.kw_defaults.append(None)
            scanned.args.kwarg=None
        super().__init__(compiler,name,scanned,parent=parent,kind=kind)
        self.node=node
        lexical_name={'generator':'<genexpr>','lambda':'<lambda>'}.get(kind,getattr(node,'name',None))
        code=compiler.lexical_codes[(node.lineno,lexical_name)]
        names=tuple(dict.fromkeys((*code.co_varnames,*code.co_cellvars)))
        if names[:len(self.parameters)]!=tuple(self.parameters):
            raise ValueError('native-build physical parameter order differs')
        self.locals,self.next_slot={},0
        self.temporary_slots,self.cell_slots=set(),set()
        handler_names={n.name for n in ast.walk(node) if isinstance(n,ast.ExceptHandler) and n.name}
        for local_name in names:
            slot=self.local(local_name)
            if local_name in handler_names:self.temporary_slots.add(slot.slot)
        for local_name in code.co_cellvars:self.cell_slots.add(self.locals[local_name].slot)
        for free_name in code.co_freevars:
            if parent is None:raise ValueError('native-build top-level entry has a free cell')
            outer=parent.variable(free_name)
            if outer is None:raise ValueError('native-build closure has no original cell')
            parent.cell_slots.add(outer.slot)
            self.captures[free_name]=(self.slot(False),outer)
        self.lexical_names,self.lexical_cells,self.lexical_freevars=names,code.co_cellvars,code.co_freevars
        self.read_kinds={ref.slot:(name,0) for name,ref in self.locals.items()}
        self.read_kinds.update({pair[0].slot:(name,1) for name,pair in self.captures.items()})

    def copy(self,value):
        if value.slot in self.read_kinds:
            name,role=self.read_kinds[value.slot]
            return self.effect('STORE',(value,),raw=(self.compiler.literal(name),role))
        return super().copy(value)

    def comp_scope(self,generators,*,generator=False):
        if generator:
            names={n.id for value in generators for n in ast.walk(value.target)
                   if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Store)}
            return {name:self.local(name) for name in sorted(names)}
        return super().comp_scope(generators,generator=generator)

    def condition(self,node,yes,no):
        if isinstance(node,ast.Compare) and len(node.ops)>1:
            left=self.expression(node.left)
            for index,(operation,expression) in enumerate(zip(node.ops,node.comparators)):
                right=self.expression(expression); last=index==len(node.ops)-1
                value=self.effect('COMPARE',(left,right),raw=(COMPARE[type(operation).__name__],),
                                  consume=(left,right) if last else (left,))
                if last:self.truth(value,yes,no)
                else:
                    onward,failed=self.label(),self.label()
                    self.truth(value,onward,failed); self.mark(failed)
                    self.release((right,)); self.jump(no); self.mark(onward); left=right
            return
        return super().condition(node,yes,no)

    def expression(self,node):
        if isinstance(node,ast.BoolOp):
            result,done=self.slot(),self.label()
            for index,child in enumerate(node.values):
                self.store(result,self.expression(child))
                if index!=len(node.values)-1:
                    onward=self.label()
                    self.truth(self.copy(result),onward if isinstance(node.op,ast.And) else done,
                               done if isinstance(node.op,ast.And) else onward)
                    self.mark(onward); self.release((result,))
            self.mark(done); return result
        if isinstance(node,ast.Call):
            if any(isinstance(arg,ast.Starred) for arg in node.args):
                raise ValueError('native-build policy has no starred positional CALL')
            callee=self.expression(node.func)
            args=[self.expression(arg) for arg in node.args]
            if any(k.arg is None for k in node.keywords):
                if len(node.keywords)!=1 or node.keywords[0].arg is not None:
                    raise ValueError('native-build CALL has one final mapping only')
                positional=self.effect('PACK',raw=(PACK['Tuple'],),vector=args,consume=reversed(args))
                mapping=self.expression(node.keywords[0].value)
                prepared=self.effect('CALL',(callee,positional,mapping),raw=(0,MAPPING_PREPARE),consume=(mapping,))
                return self.effect('CALL',(callee,positional,prepared),raw=(0,MAPPING_CALL),
                                   consume=(callee,positional,prepared))
            keys=[self.compiler.literal(k.arg) for k in node.keywords]
            values=[self.expression(k.value) for k in node.keywords]
            return self.effect('CALL',(callee,*args,*values),raw=(len(args),len(keys),*keys),
                               consume=(callee,*args,*values))
        if isinstance(node,ast.Dict) and any(key is None for key in node.keys):
            result=self.effect('PACK',raw=(PACK['Dict'],),vector=())
            keys,values=[],[]
            def flush():
                if keys:
                    block=super(Function,self).expression(ast.Dict(keys=list(keys),values=list(values)))
                    self.effect('CALL',(result,block),raw=(0,DICT_UPDATE),destination=result,consume=(block,))
                    keys.clear(); values.clear()
            for key,value in zip(node.keys,node.values):
                if key is None:
                    flush(); mapping=self.expression(value)
                    self.effect('CALL',(result,mapping),raw=(0,DICT_UPDATE),destination=result,consume=(mapping,))
                else:
                    if not isinstance(key,ast.Constant) or type(key.value) is not str:
                        raise ValueError('native-build expanded dictionary key differs')
                    keys.append(key); values.append(value)
            flush(); return result
        return super().expression(node)

    def region_return(self,value,tag):
        marker=self.constant(tag)
        result=self.effect('PACK',raw=(PACK['Tuple'],),vector=(marker,value),consume=(value,marker))
        self.emit('return',value=result)

    def statements(self,statements):
        for node in statements:
            if isinstance(node,ast.ImportFrom):
                if node.level!=1 or node.module not in self.compiler.imports:
                    raise ValueError('native-build import outside fixed inventory')
                names=tuple(alias.name for alias in node.names)
                if any(name not in self.compiler.imports[node.module] for name in names):
                    raise ValueError('unreviewed import name')
                module=self.effect('IMPORT',raw=(0,self.compiler.literal(node.module),
                    *(self.compiler.literal(name) for name in names)))
                for alias in node.names:
                    value=self.effect('IMPORT',(module,),raw=(1,self.compiler.literal(alias.name)))
                    self.assign(ast.Name(id=alias.asname or alias.name,ctx=ast.Store()),value)
                self.release((module,))
            elif isinstance(node,ast.FunctionDef):
                if node.decorator_list or node.args.defaults or node.args.kw_defaults or node.args.kwarg or node.args.vararg:
                    raise ValueError('unreviewed native-build named closure')
                nested=self.compiler.nested(self,node,'function'); nested.compile()
                value=self.effect('FUNCTION',raw=(nested,0),vector=[p[1] for p in nested.captures.values()])
                self.assign(ast.Name(id=node.name,ctx=ast.Store()),value)
            elif isinstance(node,ast.Raise) and node.exc is None:
                self.effect('CALL',raw=(0,RERAISE),count=0)
            elif isinstance(node,ast.With):
                first=node.items[0]
                if first.optional_vars is not None and not isinstance(first.optional_vars,ast.Name):
                    raise ValueError('native-build with target must be one original local')
                body=node.body
                if len(node.items)>1:
                    nested_with=ast.With(items=node.items[1:],body=body,type_comment=None)
                    ast.copy_location(nested_with,node); body=[nested_with]
                region_node=ast.With(items=[first],body=body,type_comment=None); ast.copy_location(region_node,node)
                manager=self.expression(first.context_expr)
                nested=self.compiler.region(self,region_node); nested.compile()
                target=self.variable(first.optional_vars.id).slot if first.optional_vars else 65535
                envelope=self.effect('CALL',(manager,),raw=(nested,WITH_REGION,target),
                    vector=[p[1] for p in nested.captures.values()],consume=(manager,))
                acknowledged,result=self.effect('UNPACK',(envelope,),raw=(2,),count=2,consume=(envelope,))
                normal,suppressed,done=self.label(),self.label(),self.label()
                self.truth(acknowledged,normal,suppressed); self.mark(normal)
                tag,value=self.effect('UNPACK',(result,),raw=(2,),count=2,consume=(result,))
                returned,fallthrough=self.label(),self.label()
                self.truth(tag,returned,fallthrough); self.mark(returned)
                if self.kind=='with_region':self.region_return(value,1)
                else:self.emit('return',value=value)
                self.mark(fallthrough); self.release((value,)); self.jump(done)
                self.mark(suppressed); self.release((result,)); self.mark(done)
            elif isinstance(node,ast.Return) and self.kind=='with_region':
                self.region_return(self.expression(node.value) if node.value else self.constant(None),1)
            elif isinstance(node,ast.Continue):
                if not self.loop_stack:raise ValueError('continue has no native-build loop')
                self.jump(self.loop_stack[-1][0])
            else:
                super().statements((node,))

    def compile(self):
        if self.kind!='with_region':return super().compile()
        if getattr(self,'_compiled',False):return
        self._compiled=True
        self.statements(self.node.body)
        self.region_return(self.constant(None),0)


def compile_policy(source):
    return Compiler(source)

tools/hia_public_front_policy.py.text:
"""Exact retained public assembly and verify-routing policy for offline HIA authoring.

These function bodies are never imported or executed by the selected runtime.
The complete JSON provider and existing primitive/nominal providers remain
explicit dependencies; this owner does not claim full normalization closure.
"""

def _reject(message, *, line=None, limit=False):
    raise HIAAssemblyRejected(message, "E_HIA_ASSEMBLY_LIMIT" if limit else "E_HIA_ASSEMBLY",
                              line=line)


def _source(value):
    if type(value) not in (str, bytes):
        _reject("source must be UTF-8 text or bytes")
    if len(value) > MAX_SOURCE_BYTES:
        _reject("source exceeds byte budget", limit=True)
    try:
        raw = value.encode("utf-8") if type(value) is str else value
        if len(raw) > MAX_SOURCE_BYTES:
            _reject("source exceeds byte budget", limit=True)
        text = raw.decode("utf-8")
    except UnicodeError as exc:
        raise HIAAssemblyRejected("source is not valid UTF-8") from exc
    # LF and optional CRLF are the only line separators. Do not let Unicode
    # splitlines(), NUL, BOM or terminal controls change visible tokenization.
    # The pattern is the exact rejected set from the character-wise check:
    # ASCII controls except TAB/LF/CR, plus BOM. UTF-8 and source-size checks
    # still precede it, and the separate CRLF/line checks still follow it.
    if _SOURCE_CONTROL.search(text) is not None:
        _reject("unsupported control character or byte-order mark")
    lines = text.split("\n")
    if len(lines) > MAX_LINES:
        _reject("source exceeds line budget", limit=True)
    for number, line in enumerate(lines, 1):
        if len(line.encode("utf-8")) > MAX_LINE_BYTES:
            _reject("line exceeds byte budget", line=number, limit=True)
        if "\r" in line.removesuffix("\r"):
            _reject("carriage return must be part of CRLF", line=number)
    return raw, lines


def _items(value, line):
    if not value.strip():
        return []
    parts = [part.strip() for part in value.split(",")]
    if len(parts) > MAX_LIST_ITEMS:
        _reject("list exceeds item budget", line=line, limit=True)
    if any(not part for part in parts):
        _reject("empty list item", line=line)
    return parts


def _names(value, line):
    parts = _items(value, line)
    if any(re.fullmatch(_NAME, part) is None for part in parts):
        _reject("expected explicit ASCII names", line=line)
    return parts


def _parameters(value, line):
    result = []
    for part in _items(value, line):
        match = re.fullmatch(rf"({_NAME})\s*:\s*({_NAME})", part)
        if match is None:
            _reject("expected name:type for every value", line=line)
        result.append({"name": match[1], "type": match[2]})
    return result


def _attrs(value, line):
    if value is None:
        return {}
    try:
        preflight_hia_json(value, max_nodes=MAX_ATTRIBUTE_NODES,
                          max_depth=MAX_ATTRIBUTE_DEPTH)
        attrs = decode_json(value)
    except (ValueError, OverflowError, HIAEditRejected) as exc:
        raise HIAAssemblyRejected("attributes require bounded strict JSON", line=line) from exc
    if type(attrs) is not dict:
        _reject("attributes must be one JSON object", line=line)
    return attrs


def _parse_assembly_document(source: str | bytes) -> dict:
    """Construct a fresh syntax document without granting Core authority.

    The same source, syntax and attribute bounds apply. The returned mutable
    document is not verified; public callers use assemble_program. Internal
    fixture authors may transform it before their final independent admission.
    No parsed document, VerifiedProgram or admission result is cached.
    """
    _, lines = _source(source)
    document = None
    function = block = None
    blocks = operations = 0
    for number, raw in enumerate(lines, 1):
        line = raw.removesuffix("\r").strip(" \t")
        if not line:
            continue
        if document is None:
            match = _HEADER.fullmatch(line)
            if match is None or match[1] not in CORE_SCHEMAS:
                _reject("expected hia-asm.v1, explicit primitive v6/v7/v8 schema, and module", line=number)
            document = {"schema": match[1], "module": match[2], "functions": []}
            continue
        if function is None:
            exports = re.fullmatch(r"exports\(([^()]*)\)", line)
            if exports is not None:
                if "exports" in document or document["functions"]:
                    _reject("exports may occur once, before all functions", line=number)
                document["exports"] = _names(exports[1], number)
                continue
            match = _FUNCTION.fullmatch(line)
            if match is None:
                _reject("expected explicit function header", line=number)
            if len(document["functions"]) >= MAX_FUNCTIONS:
                _reject("function inventory exceeds budget", line=number, limit=True)
            function = {"name": match[1], "params": _parameters(match[2], number),
                        "returns": _names(match[3], number), "effects": _names(match[4], number),
                        "entry": match[5], "blocks": []}
            if match[6] is not None:
                if document["schema"] != SCHEMA_V8:
                    _reject("return_loans requires explicit Core v8", line=number)
                try:
                    preflight_hia_json(match[6], max_nodes=MAX_LIST_ITEMS + 1, max_depth=2)
                    origins = decode_json(match[6])
                except (ValueError, OverflowError, HIAEditRejected) as exc:
                    raise HIAAssemblyRejected("return_loans requires bounded strict JSON", line=number) from exc
                if (type(origins) is not list or len(origins) > MAX_LIST_ITEMS
                        or any(x is not None and (type(x) is not str or re.fullmatch(_NAME, x) is None)
                               for x in origins)):
                    _reject("return_loans requires a list of formal names or null", line=number)
                function["return_loans"] = origins
            document["functions"].append(function)
            block = None
            continue
        if line == "end":
            if block is None or "term" not in block:
                _reject("function must end after a block terminator", line=number)
            function = block = None
            continue
        match = _BLOCK.fullmatch(line)
        if match is not None:
            if block is not None and "term" not in block:
                _reject("previous block has no terminator", line=number)
            blocks += 1
            if blocks > MAX_BLOCKS:
                _reject("block inventory exceeds budget", line=number, limit=True)
            block = {"id": match[1], "params": _parameters(match[2], number), "ops": []}
            function["blocks"].append(block)
            continue
        if block is None or "term" in block:
            _reject("expected block header or function end", line=number)
        if match := _RETURN.fullmatch(line):
            block["term"] = {"op": "ret", "values": _names(match[1], number)}
        elif match := _JUMP.fullmatch(line):
            block["term"] = {"op": "jump", "target": match[1], "args": _names(match[2], number)}
        elif match := _BRANCH.fullmatch(line):
            block["term"] = {"op": "branch", "cond": match[1],
                             "then": {"target": match[2], "args": _names(match[3], number)},
                             "else": {"target": match[4], "args": _names(match[5], number)}}
        elif match := _TRAP.fullmatch(line):
            block["term"] = {"op": "trap", "code": match[1]}
        elif match := _INSTRUCTION.fullmatch(line):
            operations += 1
            if operations > MAX_OPERATIONS:
                _reject("operation inventory exceeds budget", line=number, limit=True)
            block["ops"].append({"op": match[2], "args": _names(match[3], number),
                                 "out": [] if match[1].strip() == "_" else _parameters(match[1], number),
                                 "attrs": _attrs(match[4], number)})
        else:
            _reject("expected typed instruction or explicit terminator", line=number)
    if document is None:
        _reject("missing assembly header")
    if function is not None:
        _reject("unterminated function; explicit end required", line=len(lines))
    return document


def assemble_program(source: str | bytes) -> VerifiedProgram:
    """Translate explicit assembly to Core and reverify the entire program.

    v6/v7/v8 are the text targets. Historical schemas require their existing
    explicit adapters, and nominal layouts require their existing elaborator.
    """
    document = _parse_assembly_document(source)
    try:
        return verify_program(document)
    except HIAProgramRejected as exc:
        # Core errors are kept as Core errors. An absent location is honest:
        # assigning a guessed syntax line would misidentify cross-block errors.
        raise HIAAssemblyRejected(str(exc).removeprefix(exc.code + ": "), exc.code,
                                  phase="core_verification") from exc


def _render_parameters(parameters):
    return ",".join(p["name"] + ":" + p["type"] for p in parameters)


def _render_assembly_document(data: dict) -> str:
    """Spell a construction document without claiming it is valid Core.

    The input remains owned by the caller and is only read. This helper grants
    no VerifiedProgram or execution authority and performs no admission. The
    public renderer below still fully verifies both the input and round trip.
    """
    lines = [f'{WIRE_HEADER} {data["schema"]} {data["module"]}']
    if "exports" in data:
        lines.append("exports(" + ",".join(data["exports"]) + ")")
    for function in data["functions"]:
        lines.append(f'fn {function["name"]}({_render_parameters(function["params"])}) -> '
                     f'({",".join(function["returns"])}) effects({",".join(function["effects"])}) '
                     f'entry({function["entry"]})')
        if "return_loans" in function:
            lines[-1] += " return_loans(" + json.dumps(function["return_loans"], separators=(",", ":")) + ")"
        for block in function["blocks"]:
            lines.append(f'block {block["id"]}({_render_parameters(block["params"])})')
            for instruction in block["ops"]:
                outputs = _render_parameters(instruction["out"]) or "_"
                text = f'  {outputs} = {instruction["op"]}({",".join(instruction["args"])})'
                if instruction["attrs"]:
                    text += " " + json.dumps(instruction["attrs"], sort_keys=True, separators=(",", ":"),
                                             ensure_ascii=False, allow_nan=False)
                lines.append(text)
            term = block["term"]
            if term["op"] == "ret":
                text = "ret(" + ",".join(term["values"]) + ")"
            elif term["op"] == "jump":
                text = f'jump {term["target"]}({",".join(term["args"])})'
            elif term["op"] == "branch":
                left, right = term["then"], term["else"]
                text = (f'branch {term["cond"]} {left["target"]}({",".join(left["args"])}) '
                        f'{right["target"]}({",".join(right["args"])})')
            else:
                text = "trap " + term["code"]
            lines.append("  " + text)
        lines.append("end")
    return "\n".join(lines) + "\n"


def render_assembly(document) -> str:
    """Canonical compact text whose exact primitive Core round trip is checked."""
    checked = verify_program(document)
    data = checked.as_dict()
    if checked.structured_bytes is not None or data["schema"] not in CORE_SCHEMAS:
        raise HIAAssemblyRejected("render requires explicit primitive v6/v7/v8 Core; use the existing adapter first",
                                  "E_HIA_ASSEMBLY_PROFILE", phase="representation")
    rendered = _render_assembly_document(data)
    if assemble_program(rendered).canonical_bytes != checked.canonical_bytes:
        raise HIAAssemblyRejected("renderer changed canonical Core", "E_HIA_ASSEMBLY_ROUNDTRIP",
                                  phase="representation")
    return rendered


def diagnose_assembly(source: str | bytes) -> dict:
    """Stable Agent diagnostic; accepted syntax/Core grants no native authority."""
    result = {"schema": "hepta.hia.assembly-diagnostic.v1", "accepted": False,
              "deployment_authority": False, "safety_certificate": False,
              "native_artifact_created": False}
    try:
        raw, _ = _source(source)
        result.update(source_sha256=sha256(raw).hexdigest(), source_bytes=len(raw))
        checked = assemble_program(raw)
    except HIAProgramRejected as exc:
        result["diagnostic"] = {"code": exc.code, "message": str(exc),
                                "phase": getattr(exc, "phase", "core_verification"),
                                "line": getattr(exc, "line", None)}
        return result
    result.update(accepted=True, core_sha256=checked.sha256,
                  core_schema=checked.as_dict()["schema"], diagnostic=None)
    return result


def verify_program(program) -> VerifiedProgram:
    """Check standalone operations and every CFG edge; no source/hash authority.

    Even a manually constructed VerifiedProgram is parsed and fully rechecked.
    Caller-owned dictionaries and decoded dictionaries never back execution.
    """
    if isinstance(program, VerifiedProgram) and program.structured_bytes is not None:
        if type(program.structured_bytes) is not bytes:
            _reject("structured input must be immutable canonical bytes", "E_HIA_FORMAT")
        checked = verify_program(program.structured_bytes)
        if (checked.structured_bytes != program.structured_bytes
                or checked.canonical_bytes != program.canonical_bytes):
            _reject("structured input and executable core differ", "E_HIA_CORE")
        return checked
    data, raw = _decode(program)
    if (type(data) is dict and type(data.get("schema")) is str
            and data["schema"] in COMPOSITE_SCHEMAS):
        from .hia_program_composite import elaborate_program
        # The entire input was bounded/strictly decoded above.  The whole
        # generated program is independently checked, with no receipt bypass.
        core = verify_program(elaborate_program(data))
        return VerifiedProgram(core.canonical_bytes, raw)
    if type(data) is dict and data.get("schema") == SCHEMA_V2 and "types" in data:
        _reject("historical nominal v2 requires import_legacy_composite_v2; "
                "the primitive v2 namespace cannot infer a producer profile",
                "E_HIA_VERSION_COLLISION")
    from .hia_core_admission_native import selected_core_structure
    selected = selected_core_structure(data, raw)
    if selected is not None:
        return VerifiedProgram(raw)
    functions, block_maps = _primitive_structure(data)
    interfaces = _function_interfaces(functions)
    for fn in functions.values():
        _verify_function(data["schema"], fn, block_maps[fn["name"]], interfaces)
    return VerifiedProgram(raw)

tools/hia_public_front_control.py.text:
"""Offline authoring of complete public assembly and verify routing.

The runtime receives only a HIA-emitted control table. The source's branches,
loops, local/cell layout, exception regions and one-use foreign permissions
are emitted as HIA. JSON, regex and existing semantic providers are explicit
dependencies; no original assembly/verify-routing body is a foreign port.
"""
from __future__ import annotations

import ast
from types import CodeType

from tools.hia_machine_plan_control import Compiler as _Compiler, OPS, BINARY
from tools.hia_native_build_control import Function as _Function

ENTRIES = ('_reject', '_source', '_items', '_names', '_parameters', '_attrs',
           '_parse_assembly_document', 'assemble_program', '_render_parameters',
           '_render_assembly_document', 'render_assembly', 'diagnose_assembly',
           'verify_program')
FORMAT_VALUE = 240
BUILD_STRING = 241
IMPORTS = {'hia_program_composite': ('elaborate_program',),
           'hia_core_admission_native': ('selected_core_structure',)}


class Compiler(_Compiler):
    def __init__(self, source):
        self.source, self.tree = source, ast.parse(source)
        self.lexical_codes = {}
        def remember(code):
            for child in code.co_consts:
                if isinstance(child, CodeType):
                    key = (child.co_firstlineno, child.co_name)
                    if key in self.lexical_codes:
                        raise ValueError('ambiguous public-front lexical frame')
                    self.lexical_codes[key] = child
                    remember(child)
        remember(compile(source, '<public-front-lexical-layout>', 'exec'))
        self.literals, self.literal_indices = [], {}
        self.functions, self.by_name = [], {}
        self.imports = {name: set(values) for name, values in IMPORTS.items()}
        nodes = []
        for node in self.tree.body:
            if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and type(node.value.value) is str:
                continue
            if not isinstance(node, ast.FunctionDef) or node.decorator_list:
                raise ValueError('unreviewed public-front policy declaration')
            nodes.append(node)
        if tuple(node.name for node in nodes) != ENTRIES:
            raise ValueError('complete public-front original entry inventory differs')
        for node in nodes:
            function = Function(self, node.name, node)
            self.functions.append(function)
            self.by_name[node.name] = function
        index = 0
        while index < len(self.functions):
            self.functions[index].compile()
            index += 1
        for mode, function in enumerate(self.functions, 1):
            function.mode = mode
        for function in self.functions:
            function.resolve()
        self._validate_calls()

    def nested(self, parent, node, kind):
        if kind not in ('generator', 'lambda'):
            raise ValueError('public-front has no unreviewed named/with region')
        function = Function(self, parent.name + ':' + kind + ':' + str(len(self.functions)),
                            node, parent=parent, kind=kind)
        self.functions.append(function)
        return function

    def _validate_calls(self):
        self.call_shapes, self.string_shapes = set(), set()
        for function in self.functions:
            for instruction in function.instructions:
                if instruction['kind'] != 'effect' or instruction['opcode'] != OPS['CALL']:
                    continue
                raw, args = instruction['raw'], instruction['arguments']
                if len(raw) == 2 and raw[1] in (FORMAT_VALUE, BUILD_STRING):
                    if raw[1] == FORMAT_VALUE:
                        if raw[0] != 0 or len(args) != 1:
                            raise ValueError('public-front format shape differs')
                    else:
                        if raw[0] != len(args) or len(args) < 2:
                            raise ValueError('public-front BUILD_STRING shape differs')
                        self.string_shapes.add(len(args))
                else:
                    if (len(raw) < 2 or len(raw) != 2 + raw[1]
                            or len(args) != 1 + raw[0] + raw[1]):
                        raise ValueError('public-front CALL shape differs')
                    self.call_shapes.add((raw[0], tuple(self.literals[i] for i in raw[2:])))
                if (len({r.slot for r in args}) != len(args)
                        or set(instruction['consume']) != set(args)
                        or any(not r.temporary or r.slot in function.cell_slots for r in args)):
                    raise ValueError('public-front CALL lacks unique consumed operands')


class Function(_Function):
    def __init__(self, compiler, name, node, *, parent=None, kind='function'):
        self.namespace = parent.namespace if parent is not None else int(name == 'verify_program')
        super().__init__(compiler, name, node, parent=parent, kind=kind)

    def effect(self, operation, arguments=(), **keywords):
        if operation == 'GLOBAL':
            raw = keywords.get('raw', ())
            if len(raw) != 1:
                raise ValueError('public-front global representation differs')
            keywords['raw'] = (*raw, self.namespace)
        return super().effect(operation, arguments, **keywords)

    def expression(self, node):
        if isinstance(node, ast.NamedExpr):
            if not isinstance(node.target, ast.Name):
                raise ValueError('public-front walrus target differs')
            value = self.expression(node.value)
            self.store(self.variable(node.target.id), value, consume=False)
            return value
        if isinstance(node, ast.JoinedStr):
            values = []
            for part in node.values:
                if isinstance(part, ast.Constant) and type(part.value) is str:
                    values.append(self.constant(part.value))
                elif isinstance(part, ast.FormattedValue) and part.conversion == -1 and part.format_spec is None:
                    value = self.expression(part.value)
                    values.append(self.effect('CALL', (value,), raw=(0, FORMAT_VALUE),
                                              consume=(value,)))
                else:
                    raise ValueError('unreviewed public-front string format')
            if not values:
                return self.constant('')
            if len(values) == 1:
                return values[0]
            return self.effect('CALL', values, raw=(len(values), BUILD_STRING),
                               consume=reversed(values))
        return super().expression(node)

    def statements(self, statements):
        for node in statements:
            if isinstance(node, ast.Assign) and len(node.targets) > 1:
                value = self.expression(node.value)
                for target in node.targets[:-1]:
                    self.assign(target, self.copy(value))
                self.assign(node.targets[-1], value)
            elif isinstance(node, ast.AugAssign) and isinstance(node.target, ast.Subscript):
                owner, key = self.expression(node.target.value), self.expression(node.target.slice)
                left = self.effect('ITEM', (owner, key))
                right = self.expression(node.value)
                value = self.effect('BINARY', (left, right),
                    raw=(128 + BINARY[type(node.op).__name__],), consume=(left, right))
                self.effect('SET_ITEM', (owner, key, value), count=0,
                            consume=(value, owner, key))
            else:
                super().statements((node,))


def compile_policy(source):
    return Compiler(source)

hepta/hia_public_front_native.py.text:
"""HIA-owned public assembly and verify-routing continuation.

Every policy branch, loop, construction, recursive routing and re-verification
permission is in the emitted HIA table. Python supplies fixed object/import/
format operations and explicitly retained JSON/regex/semantic providers.
This does not close arbitrary-object JSON normalization or physical C recursion.
"""
from __future__ import annotations

import builtins
from hashlib import sha256

from .hia_json_preflight_native import _source_resource_path
from .hia_machine_plan_control_native import (
    PlanFrame, NativeMachinePlanControl, _Cell, _EMPTY)
from . import hia_public_front_ports as ports

SOURCE = _source_resource_path('examples/hia_bootstrap/public_front.hiaasm')
SCHEMA = 'hepta.hia.public-front-native.v1'
SELECTOR = 'HEPTA_HIA_PUBLIC_FRONT_MANIFEST'
ARITIES = {'_reject':3, '_source':1, '_items':2, '_names':2, '_parameters':2,
           '_attrs':2, '_parse_assembly_document':1, 'assemble_program':1,
           '_render_parameters':1, '_render_assembly_document':1,
           'render_assembly':1, 'diagnose_assembly':1, 'verify_program':1}
_UNKNOWN = {}
_UNCONFIRMED_IMAGE_CLEANUP = []


class PublicFrontUnknown(RuntimeError):
    """A claimed observation has no confirmed result; it is never replayed."""


def _match_exception(frame, slot):
    try:
        frame.image._delivery.deliver(frame.error)
    except frame._get(slot) as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 1
    except BaseException as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 0
    frame._uncertain = True
    raise PublicFrontUnknown('public-front exception delivery returned')


class PublicFrontFrame(PlanFrame):
    def _global_in(self, name, group):
        if type(group) is not int or group not in (0,1):
            raise PublicFrontUnknown('public-front global namespace differs')
        namespace = self.image.namespaces[group]
        if name in namespace:
            value = namespace[name]
            helper = self.image._helpers.get(name)
            if helper is not None:
                expected = self.image.public_entries[group].get(name, _EMPTY)
                if value is expected:
                    return helper
            return value
        if name in vars(builtins):
            return vars(builtins)[name]
        raise NameError("name '"+name+"' is not defined", name=name)

    def _move(self, slot):
        value = self._get(slot)
        self._clear(slot)
        return value

    def _load_named(self, slot, name, role):
        if type(slot) is not int or not 0 <= slot < len(self.values):
            raise PublicFrontUnknown('public-front named slot differs')
        value = self.values[slot]
        if slot in self.cells:
            value = value.value
        return ports.unbound(name,role) if value is _EMPTY else value

    def _call(self, args, raw):
        if raw == (0,240):
            if len(args) != 1:
                raise PublicFrontUnknown('public-front FORMAT operands differ')
            return ports.format_value(self,args[0])
        if len(raw) == 2 and raw[1] == 241:
            primitive = ports.BUILD_STRINGS.get(raw[0])
            if primitive is None or raw[0] != len(args):
                raise PublicFrontUnknown('public-front BUILD_STRING operands differ')
            return primitive(self,args)
        if len(raw) < 2 or len(raw) != 2+raw[1] or len(args) != 1+raw[0]+raw[1]:
            raise PublicFrontUnknown('public-front CALL operands differ')
        key = raw[0], tuple(self.image.literal(i) for i in raw[2:])
        primitive = ports.CALLS.get(key)
        if primitive is None:
            raise PublicFrontUnknown('public-front CALL outside frozen inventory')
        return primitive(self,args)

    def _function(self, args, raw, vector):
        mode,generator = raw
        captures = tuple(self.values[slot] for slot in vector)
        if any(type(cell) is not _Cell for cell in captures):
            raise PublicFrontUnknown('public-front closure captured a non-cell')
        if generator == 1 and len(args) == 1:
            frame = PublicFrontFrame(self.image,mode,(self._get(args[0]),),captures,
                                     witness=self.witness)
            def native_generator():
                value = None
                try:
                    while True:
                        value = None
                        if frame.drive() == 0:
                            return
                        value = frame.take(yielded=True)
                        yield value
                finally:
                    value = None
            return native_generator()
        raise PublicFrontUnknown('public-front closure shape is outside its frozen inventory')

    def _effect(self):
        op,destinations,args,raw,vector = self._parts()
        if op == 2:
            if len(raw) != 2 or args or len(destinations) != 1 or vector:
                raise PublicFrontUnknown('public-front GLOBAL representation differs')
            self._set(destinations[0],self._global_in(self.image.literal(raw[0]),raw[1]))
            return 0
        if op == 15 and raw:
            if len(raw) != 2 or len(args) != 1 or len(destinations) != 1 or vector:
                raise PublicFrontUnknown('public-front named-load representation differs')
            self._set(destinations[0],self._load_named(args[0],self.image.literal(raw[0]),raw[1]))
            return 0
        if op == 19:
            if len(raw) < 2 or len(destinations) != 1 or vector:
                raise PublicFrontUnknown('public-front import representation differs')
            if raw[0] == 0 and not args:
                module = self.image.literal(raw[1])
                names = tuple(self.image.literal(i) for i in raw[2:])
                primitive = self.image._import_names.get((module,names))
                if primitive is None:
                    raise PublicFrontUnknown('public-front IMPORT_NAME outside frozen inventory')
                self._set(destinations[0],primitive())
            elif raw[0] == 1 and len(raw) == 2 and len(args) == 1:
                primitive = self.image._import_fields.get(self.image.literal(raw[1]))
                if primitive is None:
                    raise PublicFrontUnknown('public-front IMPORT_FROM outside frozen inventory')
                self._set(destinations[0],primitive(self._get(args[0])))
            else:
                raise PublicFrontUnknown('public-front import phase differs')
            return 0
        if op == 21:
            if len(args) != 1 or destinations or raw or vector:
                raise PublicFrontUnknown('public-front exception match differs')
            return _match_exception(self,args[0])
        return super()._effect()

    def service(self, issued):
        super().service(issued)
        if self._uncertain:
            _UNKNOWN[self.nonce] = self
            self.close(release=False)
            raise PublicFrontUnknown('public-front claimed effect has no confirmed outcome')


class NativePublicFront(NativeMachinePlanControl):
    def __init__(self, image, expected_sha256, namespaces=None):
        try:
            super().__init__(image,expected_sha256)
            self._bind_namespaces(namespaces)
        except BaseException:
            self._entry = None
            for resource in (getattr(self,'_delivery',None),getattr(self,'_mapping',None)):
                if resource is not None:
                    try:
                        resource.close()
                    except BaseException:
                        _UNCONFIRMED_IMAGE_CLEANUP.append((self,resource))
            raise

    def _bind_namespaces(self, namespaces=None):
        from . import hia_agent_assembly, hia_program
        actual = (vars(hia_agent_assembly),vars(hia_program))
        if namespaces is None:
            namespaces = actual
        if type(namespaces) is not tuple or len(namespaces) != 2 or any(type(n) is not dict for n in namespaces):
            raise TypeError('public-front requires its two actual namespace dictionaries')
        if (tuple(ARITIES) != ports.ROOT_NAMES or self.function_count != ports.FUNCTION_COUNT
                or sha256(self.table).hexdigest() != ports.TABLE_SHA256):
            raise PublicFrontUnknown('public-front actual HIA table identity differs')
        self.namespaces = namespaces
        self.public_entries = (actual[0]['_NATIVE_PUBLIC_FRONT_ENTRIES'],
                               actual[1]['_NATIVE_PUBLIC_FRONT_ENTRIES'])
        if (type(self.public_entries[0]) is not dict or type(self.public_entries[1]) is not dict
                or set(self.public_entries[0]) != set(ARITIES)
                or set(self.public_entries[1]) != {'verify_program'}):
            raise PublicFrontUnknown('public-front fixed entry anchor inventory differs')
        self._import_names,self._import_fields = ports.import_ports(namespaces[1])
        self.modes = {name:(mode,arity) for mode,(name,arity) in enumerate(ARITIES.items(),1)}
        for mode,arity in self.modes.values():
            if self.function(mode)[2] != arity:
                raise PublicFrontUnknown('public-front original entry arity differs')
        for mode in range(len(ARITIES)+1,self.function_count+1):
            if self.function(mode)[2]&65535 != 1 or not self.function(mode)[2]&(1<<16):
                raise PublicFrontUnknown('public-front lazy frame arity differs')
        owner = self
        def reject(message, *, line=None, limit=False):
            frame=owner.prepare('_reject',(message,line,limit));message=line=limit=None
            return owner.finish(frame)
        def source(value):
            frame=owner.prepare('_source',(value,));value=None
            return owner.finish(frame)
        def items(value,line):
            frame=owner.prepare('_items',(value,line));value=line=None
            return owner.finish(frame)
        def names(value,line):
            frame=owner.prepare('_names',(value,line));value=line=None
            return owner.finish(frame)
        def parameters(value,line):
            frame=owner.prepare('_parameters',(value,line));value=line=None
            return owner.finish(frame)
        def attrs(value,line):
            frame=owner.prepare('_attrs',(value,line));value=line=None
            return owner.finish(frame)
        def parse(source):
            frame=owner.prepare('_parse_assembly_document',(source,));source=None
            return owner.finish(frame)
        def assemble(source):
            frame=owner.prepare('assemble_program',(source,));source=None
            return owner.finish(frame)
        def render_parameters(parameters):
            frame=owner.prepare('_render_parameters',(parameters,));parameters=None
            return owner.finish(frame)
        def render_document(data):
            frame=owner.prepare('_render_assembly_document',(data,));data=None
            return owner.finish(frame)
        def render(document):
            frame=owner.prepare('render_assembly',(document,));document=None
            return owner.finish(frame)
        def diagnose(source):
            frame=owner.prepare('diagnose_assembly',(source,));source=None
            return owner.finish(frame)
        def verify(program):
            frame=owner.prepare('verify_program',(program,));program=None
            return owner.finish(frame)
        self._helpers = dict(zip(ARITIES,(reject,source,items,names,parameters,attrs,parse,assemble,
            render_parameters,render_document,render,diagnose,verify)))
        for name,function in self._helpers.items():
            anchor = self.public_entries[int(name=='verify_program')][name]
            function.__name__ = anchor.__name__
            function.__qualname__ = anchor.__qualname__
            function.__module__ = anchor.__module__

    def prepare(self, name, arguments, *, witness=None):
        mode,arity = self.modes[name]
        if type(arguments) is not tuple or len(arguments) != arity:
            raise TypeError('public-front argument binding differs')
        return PublicFrontFrame(self,mode,arguments,witness=witness)

    def finish(self, frame):
        completed = False
        try:
            if frame.drive()!=0:
                raise PublicFrontUnknown('public-front root unexpectedly yielded')
            completed = True
            return frame.take()
        except BaseException:
            completed = False
            raise
        finally:
            frame.close(release=completed)

    def run(self, name, *arguments, witness=None):
        frame=self.prepare(name,arguments,witness=witness);arguments=None
        return self.finish(frame)

